public static String toBinary(int n) {
    if (n < 2) {
        return "" + n;
    }
    return toBinary(n / 2) + n % 2;
}

public static int countOnes(int n) {
    if (n == 0) {
        return 0;
    }
    return n % 2 + countOnes(n / 2);
}

